}

/// Helper that renders a slice of API keys without revealing their values.
///
/// Formats as `[<redacted>; N]` for a non-empty list of `N` keys, and `[]` for
/// an empty list.
struct RedactedApiKeys<'a>(&'a [String]);

impl fmt::Debug for RedactedApiKeys<'_> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if self.0.is_empty() {
            write!(f, "[]")
        } else {
            write!(f, "[<redacted>; {}]", self.0.len())
        }
    }
}

