use axum::Json;
use axum::extract::{Request, State};
use axum::http::{Method, StatusCode, header};
use axum::middleware::Next;
use axum::response::{IntoResponse, Response};
use serde_json::json;

use crate::state::AppState;

/// Route prefixes that require a valid API key when authentication is enabled.
const GUARDED_PREFIXES: &[&str] = &["/v1", "/v2", "/inference"];

/// Whether `path` falls under one of the guarded route prefixes.
///
/// A path is guarded when it equals a prefix exactly (e.g. `/v1`) or lives
/// beneath it (e.g. `/v1/models`). Sibling paths that merely share a textual
/// prefix (e.g. `/version`) are not guarded.
fn is_guarded_path(path: &str) -> bool {
    GUARDED_PREFIXES.iter().any(|prefix| {
        path == *prefix || path.strip_prefix(prefix).is_some_and(|rest| rest.starts_with('/'))
    })
}

/// Reject requests to guarded routes that do not carry a valid
/// `Authorization: Bearer <key>` header.
///
/// `OPTIONS` requests and requests to routes outside the guarded prefixes
/// (such as `/health`) are always allowed through without authentication.
pub async fn require_api_key(
    State(state): State<Arc<AppState>>,
    req: Request,
    next: Next,
) -> Response {
    // CORS preflight and non-guarded routes never require authentication.
    if req.method() == Method::OPTIONS || !is_guarded_path(req.uri().path()) {
        return next.run(req).await;
    }

    let authorized = req
        .headers()
        .get(header::AUTHORIZATION)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.strip_prefix("Bearer "))
        .is_some_and(|token| state.is_valid_api_key(token));

    if authorized {
        next.run(req).await
    } else {
        (StatusCode::UNAUTHORIZED, Json(json!({ "error": "Unauthorized" }))).into_response()
    }
}

